bases=json.loads("{\"src/canvaspilot/api.py\":{\"content\":\"\\\"\\\"\\\"High-level Canvas operations (full REST including quizzes).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport re\\nfrom copy import deepcopy\\nfrom datetime import datetime\\nfrom html import unescape\\nfrom math import isfinite\\nfrom typing import Any\\n\\nfrom canvaspilot.assignment_submission import project_assignment_submission\\nfrom canvaspilot.client import CanvasClient\\nfrom canvaspilot.feedback import build_submission_feedback\\n\\nTAG_RE = re.compile(r\\\"<[^>]+>\\\")\\nWS_RE = re.compile(r\\\"\\\\s+\\\")\\n\\n\\ndef _validate_sync_limits(limit_courses: int, limit_assignments_per_course: int) -> None:\\n    for name, value in (\\n        (\\\"limit_courses\\\", limit_courses),\\n        (\\\"limit_assignments_per_course\\\", limit_assignments_per_course),\\n    ):\\n        if type(value) is not int or value <= 0:\\n            raise ValueError(f\\\"{name} must be a positive integer\\\")\\n\\n\\ndef _sync_due_key(row: dict[str, Any]) -> tuple[int, datetime | None]:\\n    \\\"\\\"\\\"Order aware timestamps by instant, leaving all unknown dates stable at the end.\\\"\\\"\\\"\\n    raw = row.get(\\\"due_at\\\")\\n    if isinstance(raw, str):\\n        try:\\n            value = datetime.fromisoformat(raw)\\n            if value.utcoffset() is not None:\\n                # Direct comparison avoids UTC conversion overflow at years 1/9999.\\n                return (0, value)\\n        except ValueError:\\n            pass\\n    return (1, None)\\n\\n\\ndef assert_canvas_api_path(path: str) -> str:\\n    \\\"\\\"\\\"Allow only relative Canvas REST paths under ``/api/v1`` (no absolute URLs).\\\"\\\"\\\"\\n    p = (path or \\\"\\\").strip()\\n    if not p.startswith(\\\"/api/v1\\\"):\\n        raise ValueError(\\\"path must start with /api/v1 (Canvas REST only)\\\")\\n    if \\\"://\\\" in p or \\\"..\\\" in p or p.startswith(\\\"//\\\"):\\n        raise ValueError(\\\"absolute URLs and path traversal are not allowed\\\")\\n    return p\\n\\n\\ndef strip_html(html: str | None) -> str:\\n    if not html:\\n        return \\\"\\\"\\n    # Remove literal markup tags BEFORE unescaping entities: text that was\\n    # escaped (e.g. \\\"&lt;canvas&gt;\\\") must survive as text, not be mistaken\\n    # for a tag and deleted.\\n    text = TAG_RE.sub(\\\" \\\", html)\\n    return WS_RE.sub(\\\" \\\", unescape(text)).strip()\\n\\n\\ndef _brief_rubric(rubric: Any, warnings: list[str]) -> list[dict[str, Any]] | None:\\n    \\\"\\\"\\\"Project supplied rubric details without inventing missing grading data.\\\"\\\"\\\"\\n    if rubric is None:\\n        return None\\n    if not isinstance(rubric, list):\\n        warnings.append(\\\"rubric: expected a list; rubric unavailable\\\")\\n        return None\\n\\n    def record_fields(value: Any, path: str, *, criterion: bool) -> dict[str, Any] | None:\\n        if not isinstance(value, dict):\\n            warnings.append(f\\\"{path}: expected an object; entry omitted\\\")\\n            return None\\n        fields = {\\\"id\\\", \\\"description\\\", \\\"long_description\\\", \\\"points\\\"}\\n        if criterion:\\n            fields |= {\\n                \\\"criterion_use_range\\\", \\\"ignore_for_scoring\\\", \\\"learning_outcome_id\\\",\\n                \\\"outcome_id\\\", \\\"vendor_guid\\\",\\n            }\\n        result: dict[str, Any] = {}\\n        for key, field in value.items():\\n            if key not in fields:\\n                continue\\n            if field is None:\\n                valid = True\\n            elif key == \\\"points\\\":\\n                valid = type(field) is int or (type(field) is float and isfinite(field))\\n            elif key in {\\\"criterion_use_range\\\", \\\"ignore_for_scoring\\\"}:\\n                valid = isinstance(field, bool)\\n            elif key in {\\\"id\\\", \\\"learning_outcome_id\\\", \\\"outcome_id\\\"}:\\n                valid = type(field) in (str, int)\\n            else:\\n                valid = isinstance(field, str)\\n            if valid:\\n                result[key] = field\\n            else:\\n                warnings.append(f\\\"{path}.{key}: invalid value; field omitted\\\")\\n        if criterion and \\\"ratings\\\" in value:\\n            ratings = value[\\\"ratings\\\"]\\n            if ratings is None:\\n                result[\\\"ratings\\\"] = None\\n            elif isinstance(ratings, list):\\n                result[\\\"ratings\\\"] = []\\n                for index, rating in enumerate(ratings):\\n                    item = record_fields(rating, f\\\"{path}.ratings[{index}]\\\", criterion=False)\\n                    if item is not None:\\n                        result[\\\"ratings\\\"].append(item)\\n            else:\\n                warnings.append(f\\\"{path}.ratings: expected a list; ratings unavailable\\\")\\n                result[\\\"ratings\\\"] = None\\n        if not result:\\n            warnings.append(f\\\"{path}: no usable rubric fields; entry omitted\\\")\\n            return None\\n        return result\\n\\n    result = []\\n    for index, criterion in enumerate(rubric):\\n        item = record_fields(criterion, f\\\"rubric[{index}]\\\", criterion=True)\\n        if item is not None:\\n            result.append(item)\\n    return result\\n\\n\\nclass CanvasAPI:\\n    def __init__(self, client: CanvasClient | None = None) -> None:\\n        self.client = client or CanvasClient()\\n\\n    def close(self) -> None:\\n        self.client.close()\\n\\n    def __enter__(self) -> CanvasAPI:  # noqa: PYI034 — false positive, returns self (verified by isolated repro)\\n        return self\\n\\n    def __exit__(self, *args: object) -> None:\\n        self.close()\\n\\n    def whoami(self) -> dict[str, Any]:\\n        profile = self.client.request(\\\"GET\\\", \\\"/api/v1/users/self/profile\\\")\\n        return {\\n            \\\"mode\\\": self.client.mode,\\n            \\\"base_url\\\": self.client.base_url,\\n            \\\"profile\\\": profile,\\n        }\\n\\n    def get_course(self, course_id: int | str) -> dict[str, Any]:\\n        return self.client.request(\\n            \\\"GET\\\",\\n            f\\\"/api/v1/courses/{course_id}\\\",\\n            params={\\\"include[]\\\": [\\\"syllabus_body\\\", \\\"term\\\", \\\"total_scores\\\"]},\\n        )\\n\\n    def list_courses(self, *, enrollment_state: str = \\\"active\\\") -> list[dict[str, Any]]:\\n        rows = self.client.get_paginated(\\n            \\\"/api/v1/courses\\\",\\n            params=[\\n                (\\\"enrollment_state\\\", enrollment_state),\\n                (\\\"include[]\\\", \\\"term\\\"),\\n                (\\\"include[]\\\", \\\"total_scores\\\"),\\n            ],\\n        )\\n        return [\\n            {\\n                \\\"id\\\": c.get(\\\"id\\\"),\\n                \\\"name\\\": c.get(\\\"name\\\"),\\n                \\\"course_code\\\": c.get(\\\"course_code\\\"),\\n                \\\"enrollment_term_id\\\": c.get(\\\"enrollment_term_id\\\"),\\n                \\\"term\\\": (c.get(\\\"term\\\") or {}).get(\\\"name\\\"),\\n            }\\n            for c in rows\\n            if isinstance(c, dict) and c.get(\\\"id\\\")\\n        ]\\n\\n    def list_assignments(\\n        self,\\n        course_id: int | str,\\n        *,\\n        bucket: str | None = \\\"upcoming\\\",\\n        detail: str = \\\"compact\\\",\\n    ) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"List assignments. ``detail=compact`` (default) omits description bodies — use get_assignment for full text.\\\"\\\"\\\"\\n        params: list[tuple[str, Any]] = [(\\\"order_by\\\", \\\"due_at\\\"), (\\\"include[]\\\", \\\"submission\\\")]\\n        if bucket:\\n            params.append((\\\"bucket\\\", bucket))\\n        rows = self.client.get_paginated(\\n            f\\\"/api/v1/courses/{course_id}/assignments\\\",\\n            params=params,\\n        )\\n        out = []\\n        full = str(detail or \\\"compact\\\").lower() in {\\\"full\\\", \\\"verbose\\\", \\\"all\\\"}\\n        for a in rows:\\n            if not isinstance(a, dict):\\n                continue\\n            row: dict[str, Any] = {\\n                \\\"id\\\": a.get(\\\"id\\\"),\\n                \\\"course_id\\\": course_id,\\n                \\\"name\\\": a.get(\\\"name\\\"),\\n                \\\"due_at\\\": a.get(\\\"due_at\\\"),\\n                \\\"points_possible\\\": a.get(\\\"points_possible\\\"),\\n                \\\"submission_types\\\": a.get(\\\"submission_types\\\"),\\n                \\\"html_url\\\": a.get(\\\"html_url\\\"),\\n                \\\"has_submitted_submissions\\\": a.get(\\\"has_submitted_submissions\\\"),\\n            }\\n            row[\\\"submission\\\"], row[\\\"submission_warnings\\\"] = project_assignment_submission(\\n                a.get(\\\"submission\\\")\\n            )\\n            if full:\\n                row[\\\"description_text\\\"] = strip_html(a.get(\\\"description\\\"))\\n            out.append(row)\\n        return out\\n\\n    def get_assignment(self, course_id: int | str, assignment_id: int | str) -> dict[str, Any]:\\n        a = self.client.request(\\n            \\\"GET\\\",\\n            f\\\"/api/v1/courses/{course_id}/assignments/{assignment_id}\\\",\\n            params={\\\"include[]\\\": [\\\"submission\\\"]},\\n        )\\n        return {\\n            \\\"id\\\": a.get(\\\"id\\\"),\\n            \\\"course_id\\\": course_id,\\n            \\\"name\\\": a.get(\\\"name\\\"),\\n            \\\"due_at\\\": a.get(\\\"due_at\\\"),\\n            \\\"points_possible\\\": a.get(\\\"points_possible\\\"),\\n            \\\"submission_types\\\": a.get(\\\"submission_types\\\"),\\n            \\\"html_url\\\": a.get(\\\"html_url\\\"),\\n            \\\"description_html\\\": a.get(\\\"description\\\"),\\n            \\\"description_text\\\": strip_html(a.get(\\\"description\\\")),\\n            \\\"rubric\\\": a.get(\\\"rubric\\\"),\\n            \\\"rubric_settings\\\": a.get(\\\"rubric_settings\\\"),\\n            \\\"use_rubric_for_grading\\\": a.get(\\\"use_rubric_for_grading\\\"),\\n            \\\"submission\\\": a.get(\\\"submission\\\"),\\n        }\\n\\n    def assignment_brief(self, course_id: int | str, assignment_id: int | str) -> dict[str, Any]:\\n        a = self.get_assignment(course_id, assignment_id)\\n        warnings: list[str] = []\\n        rubric = _brief_rubric(a.get(\\\"rubric\\\"), warnings)\\n        settings = a.get(\\\"rubric_settings\\\")\\n        if settings is not None and not isinstance(settings, dict):\\n            warnings.append(\\\"rubric_settings: expected an object; settings unavailable\\\")\\n            settings = None\\n        use_for_grading = a.get(\\\"use_rubric_for_grading\\\")\\n        if use_for_grading is not None and not isinstance(use_for_grading, bool):\\n            warnings.append(\\\"use_rubric_for_grading: expected a boolean; grading use unknown\\\")\\n            use_for_grading = None\\n        return {\\n            \\\"title\\\": a.get(\\\"name\\\"),\\n            \\\"due_at\\\": a.get(\\\"due_at\\\"),\\n            \\\"points_possible\\\": a.get(\\\"points_possible\\\"),\\n            \\\"submission_types\\\": a.get(\\\"submission_types\\\"),\\n            \\\"prompt\\\": a.get(\\\"description_text\\\"),\\n            \\\"html_url\\\": a.get(\\\"html_url\\\"),\\n            \\\"course_id\\\": course_id,\\n            \\\"assignment_id\\\": assignment_id,\\n            \\\"rubric\\\": rubric,\\n            \\\"rubric_settings\\\": deepcopy(settings),\\n            \\\"use_rubric_for_grading\\\": use_for_grading,\\n            \\\"rubric_warnings\\\": warnings,\\n        }\\n\\n    def list_announcements(\\n        self,\\n        course_ids: list[int | str],\\n        *,\\n        start_date: str | None = None,\\n        detail: str = \\\"compact\\\",\\n    ) -> list[dict[str, Any]]:\\n        params: list[tuple[str, Any]] = [\\n            (\\\"active_only\\\", True),\\n            (\\\"per_page\\\", 50),\\n        ]\\n        for cid in course_ids:\\n            params.append((\\\"context_codes[]\\\", f\\\"course_{cid}\\\"))\\n        if start_date:\\n            params.append((\\\"start_date\\\", start_date))\\n        rows = self.client.get_paginated(\\\"/api/v1/announcements\\\", params=params)\\n        if not isinstance(rows, list):\\n            rows = [rows] if rows else []\\n        full = str(detail or \\\"compact\\\").lower() in {\\\"full\\\", \\\"verbose\\\", \\\"all\\\"}\\n        out = []\\n        for a in rows:\\n            if not isinstance(a, dict):\\n                continue\\n            text = strip_html(a.get(\\\"message\\\")) or \\\"\\\"\\n            if not full and len(text) > 400:\\n                text = text[:400] + \\\"…\\\"\\n            out.append(\\n                {\\n                    \\\"id\\\": a.get(\\\"id\\\"),\\n                    \\\"title\\\": a.get(\\\"title\\\"),\\n                    \\\"posted_at\\\": a.get(\\\"posted_at\\\"),\\n                    \\\"context_code\\\": a.get(\\\"context_code\\\"),\\n                    \\\"message_text\\\": text,\\n                    \\\"html_url\\\": a.get(\\\"html_url\\\"),\\n                }\\n            )\\n        return out\\n\\n    def list_modules(self, course_id: int | str, *, detail: str = \\\"compact\\\") -> list[dict[str, Any]]:\\n        rows = self.client.get_paginated(\\n            f\\\"/api/v1/courses/{course_id}/modules\\\",\\n            params={\\\"include[]\\\": [\\\"items\\\"]},\\n        )\\n\\n        def valid_items(value: Any) -> bool:\\n            return isinstance(value, list) and all(\\n                isinstance(item, dict)\\n                and isinstance(item.get(\\\"id\\\"), (int, str))\\n                and re.fullmatch(r\\\"[0-9]+\\\", str(item[\\\"id\\\"]))\\n                for item in value\\n            )\\n\\n        modules = []\\n        for module in rows:\\n            if not isinstance(module, dict):\\n                modules.append(module)\\n                continue\\n            inline = module.get(\\\"items\\\")\\n            count = module.get(\\\"items_count\\\")\\n            if not valid_items(inline) or (type(count) is int and len(inline) < count):\\n                # Canvas may omit inline items even when include[]=items was\\n                # requested. Resolve them before projecting either detail mode.\\n                if inline is None and type(count) is int and count == 0:\\n                    items = []\\n                else:\\n                    module_id = module.get(\\\"id\\\")\\n                    if not isinstance(module_id, (int, str)) or not re.fullmatch(r\\\"[0-9]+\\\", str(module_id)):\\n                        raise ValueError(\\\"Cannot retrieve module items without a valid module ID\\\")\\n                    items = self.client.get_paginated(\\n                        f\\\"/api/v1/courses/{course_id}/modules/{module_id}/items\\\"\\n                    )\\n                    if not valid_items(items):\\n                        raise ValueError(\\\"Canvas returned malformed module items\\\")\\n                # Do not mutate fixture data or another caller's response object.\\n                module = {**module, \\\"items\\\": items}\\n            modules.append(module)\\n        full = str(detail or \\\"compact\\\").lower() in {\\\"full\\\", \\\"verbose\\\", \\\"all\\\"}\\n        if full:\\n            return modules\\n        out = []\\n        for m in modules:\\n            if not isinstance(m, dict):\\n                continue\\n            items = []\\n            for it in m.get(\\\"items\\\") or []:\\n                if not isinstance(it, dict):\\n                    continue\\n                items.append(\\n                    {\\n                        \\\"id\\\": it.get(\\\"id\\\"),\\n                        \\\"title\\\": it.get(\\\"title\\\"),\\n                        \\\"type\\\": it.get(\\\"type\\\"),\\n                        \\\"html_url\\\": it.get(\\\"html_url\\\"),\\n                        \\\"content_id\\\": it.get(\\\"content_id\\\"),\\n                        \\\"external_url\\\": it.get(\\\"external_url\\\"),\\n                    }\\n                )\\n            out.append(\\n                {\\n                    \\\"id\\\": m.get(\\\"id\\\"),\\n                    \\\"name\\\": m.get(\\\"name\\\"),\\n                    \\\"position\\\": m.get(\\\"position\\\"),\\n                    \\\"published\\\": m.get(\\\"published\\\"),\\n                    \\\"items_count\\\": m.get(\\\"items_count\\\"),\\n                    \\\"items\\\": items,\\n                }\\n            )\\n        return out\\n\\n    def module_progress(\\n        self, course_id: int | str, *, module_id: int | str | None = None,\\n    ) -> dict[str, Any]:\\n        \\\"\\\"\\\"Read Canvas-declared module progress and a course study checklist.\\\"\\\"\\\"\\n        from canvaspilot.module_progress import module_progress\\n\\n        return module_progress(self, course_id, module_id=module_id)\\n\\n    def list_pages(self, course_id: int | str) -> list[dict[str, Any]]:\\n        rows = self.client.get_paginated(f\\\"/api/v1/courses/{course_id}/pages\\\")\\n        return [\\n            {\\n                \\\"url\\\": p.get(\\\"url\\\"),\\n                \\\"title\\\": p.get(\\\"title\\\"),\\n                \\\"published\\\": p.get(\\\"published\\\"),\\n                \\\"updated_at\\\": p.get(\\\"updated_at\\\"),\\n                \\\"front_page\\\": p.get(\\\"front_page\\\"),\\n            }\\n            for p in rows\\n            if isinstance(p, dict)\\n        ]\\n\\n    def get_page(self, course_id: int | str, page_url: str) -> dict[str, Any]:\\n        p = self.client.request(\\\"GET\\\", f\\\"/api/v1/courses/{course_id}/pages/{page_url}\\\")\\n        return {\\n            \\\"url\\\": p.get(\\\"url\\\"),\\n            \\\"title\\\": p.get(\\\"title\\\"),\\n            \\\"body_html\\\": p.get(\\\"body\\\"),\\n            \\\"body_text\\\": strip_html(p.get(\\\"body\\\")),\\n            \\\"published\\\": p.get(\\\"published\\\"),\\n        }\\n\\n    def list_discussion_topics(self, course_id: int | str) -> list[dict[str, Any]]:\\n        rows = self.client.get_paginated(\\n            f\\\"/api/v1/courses/{course_id}/discussion_topics\\\",\\n            params={\\\"order_by\\\": \\\"recent_activity\\\", \\\"only_announcements\\\": False},\\n        )\\n        return [\\n            {\\n                \\\"id\\\": t.get(\\\"id\\\"),\\n                \\\"title\\\": t.get(\\\"title\\\"),\\n                \\\"posted_at\\\": t.get(\\\"posted_at\\\"),\\n                \\\"published\\\": t.get(\\\"published\\\"),\\n                \\\"message_text\\\": strip_html(t.get(\\\"message\\\")),\\n                \\\"html_url\\\": t.get(\\\"html_url\\\"),\\n            }\\n            for t in rows\\n            if isinstance(t, dict)\\n        ]\\n\\n    def get_discussion(self, course_id: int | str, topic_id: int | str) -> dict[str, Any]:\\n        topic = self.client.request(\\n            \\\"GET\\\",\\n            f\\\"/api/v1/courses/{course_id}/discussion_topics/{topic_id}\\\",\\n        )\\n        view = self.client.request(\\n            \\\"GET\\\",\\n            f\\\"/api/v1/courses/{course_id}/discussion_topics/{topic_id}/view\\\",\\n        )\\n        return {\\\"topic\\\": topic, \\\"view\\\": view}\\n\\n    def post_discussion_reply(\\n        self,\\n        course_id: int | str,\\n        topic_id: int | str,\\n        message: str,\\n    ) -> dict[str, Any]:\\n        return self.client.request(\\n            \\\"POST\\\",\\n            f\\\"/api/v1/courses/{course_id}/discussion_topics/{topic_id}/entries\\\",\\n            data={\\\"message\\\": message},\\n        )\\n\\n    def list_files(self, course_id: int | str) -> list[dict[str, Any]]:\\n        try:\\n            rows = self.client.get_paginated(f\\\"/api/v1/courses/{course_id}/files\\\")\\n        except Exception:\\n            folders = self.client.request(\\n                \\\"GET\\\",\\n                f\\\"/api/v1/courses/{course_id}/folders/by_path\\\",\\n            )\\n            root = folders[0] if isinstance(folders, list) and folders else None\\n            if not root:\\n                raise\\n            rows = self.client.get_paginated(f\\\"/api/v1/folders/{root['id']}/files\\\")\\n        return [\\n            {\\n                \\\"id\\\": f.get(\\\"id\\\"),\\n                \\\"display_name\\\": f.get(\\\"display_name\\\"),\\n                \\\"filename\\\": f.get(\\\"filename\\\"),\\n                \\\"size\\\": f.get(\\\"size\\\"),\\n                \\\"updated_at\\\": f.get(\\\"updated_at\\\"),\\n                \\\"url\\\": f.get(\\\"url\\\"),\\n                \\\"content_type\\\": f.get(\\\"content-type\\\") or f.get(\\\"content_type\\\"),\\n            }\\n            for f in rows\\n            if isinstance(f, dict)\\n        ]\\n\\n    def browse_files(\\n        self,\\n        course_id: int | str,\\n        folder_id: int | str = \\\"root\\\",\\n        *,\\n        folders_page: int = 1,\\n        files_page: int = 1,\\n        per_page: int = 50,\\n    ) -> dict[str, Any]:\\n        \\\"\\\"\\\"Browse one course folder and bounded direct-child metadata pages.\\\"\\\"\\\"\\n        from canvaspilot.folder_browser import browse_course_folder\\n\\n        return browse_course_folder(\\n            self.client, course_id, folder_id,\\n            folders_page=folders_page, files_page=files_page, per_page=per_page,\\n        )\\n\\n    def list_quizzes(self, course_id: int | str) -> list[dict[str, Any]]:\\n        rows = self.client.get_paginated(f\\\"/api/v1/courses/{course_id}/quizzes\\\")\\n        return [\\n            {\\n                \\\"id\\\": q.get(\\\"id\\\"),\\n                \\\"title\\\": q.get(\\\"title\\\"),\\n                \\\"due_at\\\": q.get(\\\"due_at\\\"),\\n                \\\"lock_at\\\": q.get(\\\"lock_at\\\"),\\n                \\\"question_count\\\": q.get(\\\"question_count\\\"),\\n                \\\"points_possible\\\": q.get(\\\"points_possible\\\"),\\n                \\\"published\\\": q.get(\\\"published\\\"),\\n                \\\"quiz_type\\\": q.get(\\\"quiz_type\\\"),\\n                \\\"html_url\\\": q.get(\\\"html_url\\\"),\\n            }\\n            for q in rows\\n            if isinstance(q, dict)\\n        ]\\n\\n    def get_quiz(self, course_id: int | str, quiz_id: int | str) -> dict[str, Any]:\\n        return self.client.request(\\\"GET\\\", f\\\"/api/v1/courses/{course_id}/quizzes/{quiz_id}\\\")\\n\\n    def list_quiz_questions(self, course_id: int | str, quiz_id: int | str) -> list[Any]:\\n        return self.client.get_paginated(\\n            f\\\"/api/v1/courses/{course_id}/quizzes/{quiz_id}/questions\\\"\\n        )\\n\\n    def list_quiz_submissions(self, course_id: int | str, quiz_id: int | str) -> Any:\\n        return self.client.request(\\n            \\\"GET\\\",\\n            f\\\"/api/v1/courses/{course_id}/quizzes/{quiz_id}/submissions\\\",\\n        )\\n\\n    def start_quiz_submission(\\n        self,\\n        course_id: int | str,\\n        quiz_id: int | str,\\n        *,\\n        access_code: str | None = None,\\n    ) -> Any:\\n        body: dict[str, Any] = {}\\n        if access_code:\\n            body[\\\"access_code\\\"] = access_code\\n        return self.client.request(\\n            \\\"POST\\\",\\n            f\\\"/api/v1/courses/{course_id}/quizzes/{quiz_id}/submissions\\\",\\n            json_body=body if body else {},\\n        )\\n\\n    def complete_quiz_submission(\\n        self,\\n        course_id: int | str,\\n        quiz_id: int | str,\\n        submission_id: int | str,\\n        *,\\n        attempt: int | None = None,\\n        validation_token: str | None = None,\\n    ) -> Any:\\n        payload: dict[str, Any] = {}\\n        if attempt is not None:\\n            payload[\\\"attempt\\\"] = attempt\\n        if validation_token:\\n            payload[\\\"validation_token\\\"] = validation_token\\n        return self.client.request(\\n            \\\"POST\\\",\\n            f\\\"/api/v1/courses/{course_id}/quizzes/{quiz_id}/submissions/{submission_id}/complete\\\",\\n            json_body=payload,\\n        )\\n\\n    def list_conversations(self, *, scope: str = \\\"inbox\\\") -> list[Any]:\\n        return self.client.get_paginated(\\n            \\\"/api/v1/conversations\\\",\\n            params={\\\"scope\\\": scope},\\n        )\\n\\n    def get_conversation(self, conversation_id: int | str) -> Any:\\n        return self.client.request(\\\"GET\\\", f\\\"/api/v1/conversations/{conversation_id}\\\")\\n\\n    def list_calendar_events(\\n        self,\\n        *,\\n        start_date: str | None = None,\\n        end_date: str | None = None,\\n        context_codes: list[str] | None = None,\\n    ) -> list[Any]:\\n        params: list[tuple[str, Any]] = []\\n        if start_date:\\n            params.append((\\\"start_date\\\", start_date))\\n        if end_date:\\n            params.append((\\\"end_date\\\", end_date))\\n        for code in context_codes or []:\\n            params.append((\\\"context_codes[]\\\", code))\\n        return self.client.get_paginated(\\\"/api/v1/calendar_events\\\", params=params or None)\\n\\n    def submission_history(self, course_id: int | str, assignment_id: int | str) -> dict[str, Any]:\\n        \\\"\\\"\\\"Read the current self submission and exactly the history Canvas returns.\\\"\\\"\\\"\\n        from canvaspilot.submission_history import read_submission_history\\n\\n        return read_submission_history(self.client, course_id, assignment_id)\\n\\n    def submission_status(self, course_id: int | str, assignment_id: int | str) -> dict[str, Any]:\\n        return self.client.request(\\n            \\\"GET\\\",\\n            f\\\"/api/v1/courses/{course_id}/assignments/{assignment_id}/submissions/self\\\",\\n        )\\n\\n    def submission_feedback(self, course_id: int | str, assignment_id: int | str) -> dict[str, Any]:\\n        \\\"\\\"\\\"Read self submission comments and rubric evidence alongside grade/attempt metadata.\\n\\n        A false grade_matches_current_submission means grading preceded the\\n        latest resubmission. Rubric points are not used to calculate a grade.\\n        \\\"\\\"\\\"\\n        path = f\\\"/api/v1/courses/{course_id}/assignments/{assignment_id}\\\"\\n        assignment = self.client.request(\\\"GET\\\", path)\\n        submission = self.client.request(\\n            \\\"GET\\\",\\n            f\\\"{path}/submissions/self\\\",\\n            params={\\\"include[]\\\": [\\\"submission_comments\\\", \\\"rubric_assessment\\\"]},\\n        )\\n        return build_submission_feedback(assignment, submission)\\n\\n    def submit_assignment_text(\\n        self,\\n        course_id: int | str,\\n        assignment_id: int | str,\\n        body: str,\\n    ) -> dict[str, Any]:\\n        return self.client.request(\\n            \\\"POST\\\",\\n            f\\\"/api/v1/courses/{course_id}/assignments/{assignment_id}/submissions\\\",\\n            data={\\n                \\\"submission[submission_type]\\\": \\\"online_text_entry\\\",\\n                \\\"submission[body]\\\": body,\\n            },\\n        )\\n\\n    def planner_items(self, *, start_date: str | None = None, end_date: str | None = None) -> list[Any]:\\n        params: dict[str, Any] = {}\\n        if start_date:\\n            params[\\\"start_date\\\"] = start_date\\n        if end_date:\\n            params[\\\"end_date\\\"] = end_date\\n        return self.client.get_paginated(\\\"/api/v1/planner/items\\\", params=params)\\n\\n    def activity_stream(self) -> Any:\\n        return self.client.request(\\\"GET\\\", \\\"/api/v1/users/self/activity_stream\\\")\\n\\n    def list_todo_items(self) -> list[Any]:\\n        return self.client.get_paginated(\\\"/api/v1/users/self/todo\\\")\\n\\n    def list_enrollments(self, *, state: str = \\\"active\\\") -> list[Any]:\\n        return self.client.get_paginated(\\n            \\\"/api/v1/users/self/enrollments\\\",\\n            params={\\\"state[]\\\": state} if state else None,\\n        )\\n\\n    def reply_conversation(self, conversation_id: int | str, body: str) -> Any:\\n        return self.client.request(\\n            \\\"POST\\\",\\n            f\\\"/api/v1/conversations/{conversation_id}/add_message\\\",\\n            data={\\\"body\\\": body},\\n        )\\n\\n    def api_request(\\n        self,\\n        method: str,\\n        path: str,\\n        *,\\n        params: dict[str, Any] | list[tuple[str, Any]] | None = None,\\n        json_body: dict[str, Any] | None = None,\\n        data: dict[str, Any] | None = None,\\n    ) -> Any:\\n        \\\"\\\"\\\"Escape hatch: any Canvas REST call under ``/api/v1`` (session or PAT).\\\"\\\"\\\"\\n        return self.client.request(\\n            method.upper(),\\n            assert_canvas_api_path(path),\\n            params=params,\\n            json_body=json_body,\\n            data=data,\\n        )\\n\\n    def api_paginated(\\n        self,\\n        path: str,\\n        *,\\n        params: dict[str, Any] | list[tuple[str, Any]] | None = None,\\n    ) -> list[Any]:\\n        \\\"\\\"\\\"Escape hatch: paginated GET under ``/api/v1``.\\\"\\\"\\\"\\n        return self.client.get_paginated(assert_canvas_api_path(path), params=params)\\n\\n    def sync_summary(\\n        self, *, limit_courses: int = 10, limit_assignments_per_course: int = 5\\n    ) -> dict[str, Any]:\\n        \\\"\\\"\\\"Read upcoming deadlines with explicit selection counts over returned API rows.\\\"\\\"\\\"\\n        _validate_sync_limits(limit_courses, limit_assignments_per_course)\\n        returned_courses = self.list_courses()\\n        courses = returned_courses[:limit_courses]\\n        upcoming: list[dict[str, Any]] = []\\n        course_summaries: list[dict[str, Any]] = []\\n        for c in courses:\\n            try:\\n                assigns = self.list_assignments(c[\\\"id\\\"], bucket=\\\"upcoming\\\")\\n            except Exception as exc:  # noqa: BLE001 — per-course soft fail\\n                upcoming.append({\\\"course_id\\\": c[\\\"id\\\"], \\\"error\\\": str(exc)})\\n                course_summaries.append({\\n                    \\\"course_id\\\": c[\\\"id\\\"],\\n                    \\\"status\\\": \\\"error\\\",\\n                    \\\"assignments_returned\\\": None,\\n                    \\\"assignments_included\\\": None,\\n                    \\\"assignments_omitted\\\": None,\\n                    \\\"unknown_due_dates\\\": None,\\n                })\\n                continue\\n            selected = sorted(assigns, key=_sync_due_key)[:limit_assignments_per_course]\\n            upcoming.extend({**a, \\\"course_name\\\": c.get(\\\"name\\\")} for a in selected)\\n            course_summaries.append({\\n                \\\"course_id\\\": c[\\\"id\\\"],\\n                \\\"status\\\": \\\"ok\\\",\\n                \\\"assignments_returned\\\": len(assigns),\\n                \\\"assignments_included\\\": len(selected),\\n                \\\"assignments_omitted\\\": len(assigns) - len(selected),\\n                \\\"unknown_due_dates\\\": sum(1 for a in assigns if _sync_due_key(a)[0]),\\n            })\\n        return {\\n            \\\"mode\\\": self.client.mode,\\n            \\\"course_count\\\": len(courses),\\n            \\\"courses\\\": courses,\\n            \\\"upcoming_assignments\\\": sorted(upcoming, key=_sync_due_key),\\n            \\\"courses_returned\\\": len(returned_courses),\\n            \\\"courses_omitted\\\": len(returned_courses) - len(courses),\\n            \\\"limits\\\": {\\n                \\\"courses\\\": limit_courses,\\n                \\\"assignments_per_course\\\": limit_assignments_per_course,\\n            },\\n            \\\"course_summaries\\\": course_summaries,\\n        }\\n\",\"encoding\":\"utf-8\",\"sha\":\"79572cdc0391f46ad0b92ea199531371aeff2525\",\"display_url\":\"https://github.com/Jacob-Met/canvaspilot/blob/39d835c8becb04d81b65c90d1491d2d3a2727ffe/src/canvaspilot/api.py\",\"display_title\":\"api.py\"},\"src/canvaspilot/cli.py\":{\"content\":\"\\\"\\\"\\\"CLI: login + live probes.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport json\\nimport logging\\nimport sys\\nfrom pathlib import Path\\n\\n\\ndef _positive_int(value: str) -> int:\\n    try:\\n        parsed = int(value)\\n    except ValueError as exc:\\n        raise argparse.ArgumentTypeError(\\\"must be a positive integer\\\") from exc\\n    if parsed <= 0:\\n        raise argparse.ArgumentTypeError(\\\"must be a positive integer\\\")\\n    return parsed\\n\\n\\ndef main(argv: list[str] | None = None) -> None:\\n    parser = argparse.ArgumentParser(prog=\\\"canvaspilot\\\")\\n    sub = parser.add_subparsers(dest=\\\"cmd\\\", required=True)\\n\\n    login = sub.add_parser(\\\"login\\\", help=\\\"Open headed browser for Canvas SSO (one-shot)\\\")\\n    login.add_argument(\\\"--base-url\\\", default=None)\\n    login.add_argument(\\\"--profile\\\", default=None)\\n\\n    sess = sub.add_parser(\\\"session\\\", help=\\\"Stay-open session broker\\\")\\n    sess_sub = sess.add_subparsers(dest=\\\"scmd\\\", required=True)\\n    s_start = sess_sub.add_parser(\\\"start\\\", help=\\\"Start session broker (leave open)\\\")\\n    s_start.add_argument(\\\"--base-url\\\", default=None)\\n    s_start.add_argument(\\\"--profile\\\", default=None)\\n    s_start.add_argument(\\\"--port\\\", type=int, default=None)\\n    s_start.add_argument(\\n        \\\"--headless\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Headless after a prior headed login into the same profile\\\",\\n    )\\n    s_start.add_argument(\\n        \\\"--read-only\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Broker rejects non-GET/HEAD fetch ops (for unattended agent use)\\\",\\n    )\\n    sess_sub.add_parser(\\\"status\\\", help=\\\"Broker health/status\\\")\\n    sess_sub.add_parser(\\\"stop\\\", help=\\\"Shutdown broker\\\")\\n\\n    def add_common(p: argparse.ArgumentParser) -> None:\\n        p.add_argument(\\\"--base-url\\\", default=None)\\n        p.add_argument(\\\"--profile\\\", default=None)\\n        p.add_argument(\\\"--token\\\", default=None)\\n\\n    for name, help_ in [\\n        (\\\"whoami\\\", \\\"GET /users/self/profile\\\"),\\n        (\\\"courses\\\", \\\"List active courses\\\"),\\n        (\\\"sync\\\", \\\"Courses + upcoming assignments digest\\\"),\\n    ]:\\n        p = sub.add_parser(name, help=help_)\\n        add_common(p)\\n        if name == \\\"sync\\\":\\n            p.add_argument(\\\"--limit-courses\\\", type=_positive_int, default=10,\\n                           help=\\\"Maximum courses to inspect (default: 10)\\\")\\n            p.add_argument(\\\"--limit-assignments-per-course\\\", type=_positive_int, default=5,\\n                           help=\\\"Maximum assignments to include per course (default: 5)\\\")\\n\\n    assigns = sub.add_parser(\\\"assignments\\\", help=\\\"List assignments for a course\\\")\\n    add_common(assigns)\\n    assigns.add_argument(\\\"course_id\\\")\\n    assigns.add_argument(\\\"--bucket\\\", default=\\\"upcoming\\\")\\n\\n    brief = sub.add_parser(\\\"brief\\\", help=\\\"Assignment brief (cleaned prompt and supplied rubric)\\\")\\n    add_common(brief)\\n    brief.add_argument(\\\"course_id\\\")\\n    brief.add_argument(\\\"assignment_id\\\")\\n\\n    feedback = sub.add_parser(\\n        \\\"feedback\\\",\\n        help=\\\"Read self submission comments, rubric feedback, and grade/attempt metadata\\\",\\n        description=(\\n            \\\"Read self submission comments and rubric feedback. A false \\\"\\n            \\\"grade_matches_current_submission means grading preceded the latest resubmission.\\\"\\n        ),\\n    )\\n    add_common(feedback)\\n    feedback.add_argument(\\\"course_id\\\")\\n    feedback.add_argument(\\\"assignment_id\\\")\\n\\n    disc = sub.add_parser(\\\"discussions\\\", help=\\\"List discussion topics\\\")\\n    add_common(disc)\\n    disc.add_argument(\\\"course_id\\\")\\n\\n    files = sub.add_parser(\\\"files\\\", help=\\\"List course files\\\")\\n    add_common(files)\\n    files.add_argument(\\\"course_id\\\")\\n\\n    browse = sub.add_parser(\\\"browse-files\\\", help=\\\"Browse one course folder; metadata only\\\")\\n    add_common(browse)\\n    browse.add_argument(\\\"course_id\\\", help=\\\"Positive numeric Canvas course ID\\\")\\n    browse.add_argument(\\\"--folder-id\\\", default=\\\"root\\\", help=\\\"root or a returned numeric folder ID\\\")\\n    browse.add_argument(\\\"--folders-page\\\", type=int, default=1)\\n    browse.add_argument(\\\"--files-page\\\", type=int, default=1)\\n    browse.add_argument(\\\"--per-page\\\", type=int, default=50, help=\\\"Requested child-page size, 1–100\\\")\\n\\n    export = sub.add_parser(\\\"export-calendar\\\", help=\\\"Save selected assignment deadlines to a new .ics file\\\")\\n    add_common(export)\\n    export.add_argument(\\\"course_ids\\\", nargs=\\\"+\\\", type=_positive_int)\\n    export.add_argument(\\\"--out\\\", required=True, type=Path, help=\\\"New calendar file; existing paths are protected\\\")\\n    export.add_argument(\\\"--bucket\\\", choices=(\\\"upcoming\\\", \\\"past\\\", \\\"overdue\\\", \\\"undated\\\", \\\"ungraded\\\", \\\"unsubmitted\\\", \\\"all\\\"),\\n                        default=\\\"upcoming\\\", help=\\\"Canvas assignment selection (default: upcoming)\\\")\\n\\n    progress = sub.add_parser(\\\"module-progress\\\", help=\\\"Inspect reported module progress and requirements\\\")\\n    add_common(progress)\\n    progress.add_argument(\\\"course_id\\\", help=\\\"Positive numeric Canvas course ID\\\")\\n    progress.add_argument(\\\"--module-id\\\", default=None, help=\\\"Inspect one returned module ID\\\")\\n\\n    history = sub.add_parser(\\n        \\\"submission-history\\\",\\n        help=\\\"Read your returned submission versions and their submitted content\\\",\\n        description=(\\n            \\\"Read the current self submission and Canvas-returned history. \\\"\\n            \\\"Missing history stays unavailable; grades and comments are not \\\"\\n            \\\"assigned to other attempts.\\\"\\n        ),\\n    )\\n    add_common(history)\\n    history.add_argument(\\\"course_id\\\", help=\\\"Positive numeric Canvas course ID\\\")\\n    history.add_argument(\\\"assignment_id\\\", help=\\\"Positive numeric Canvas assignment ID\\\")\\n\\n    mcp = sub.add_parser(\\\"mcp\\\", help=\\\"Run MCP stdio server\\\")\\n    add_common(mcp)\\n\\n    args = parser.parse_args(argv)\\n\\n    if args.cmd == \\\"login\\\":\\n        _login(base_url=args.base_url, profile=args.profile)\\n        return\\n    if args.cmd == \\\"session\\\":\\n        _session_cmd(args)\\n        return\\n    if args.cmd == \\\"mcp\\\":\\n        from canvaspilot.mcp_server import main as mcp_main\\n\\n        mcp_main()\\n        return\\n\\n    from canvaspilot.api import CanvasAPI\\n    from canvaspilot.client import CanvasClient, default_base_url, default_profile\\n\\n    client = CanvasClient(\\n        base_url=args.base_url or default_base_url(),\\n        token=args.token,\\n        profile=Path(args.profile) if args.profile else default_profile(),\\n    )\\n    api = CanvasAPI(client)\\n    try:\\n        if args.cmd == \\\"whoami\\\":\\n            print(json.dumps(api.whoami(), indent=2, default=str))\\n        elif args.cmd == \\\"courses\\\":\\n            print(json.dumps(api.list_courses(), indent=2, default=str))\\n        elif args.cmd == \\\"sync\\\":\\n            print(json.dumps(api.sync_summary(\\n                limit_courses=args.limit_courses,\\n                limit_assignments_per_course=args.limit_assignments_per_course,\\n            ), indent=2, default=str))\\n        elif args.cmd == \\\"assignments\\\":\\n            print(\\n                json.dumps(\\n                    api.list_assignments(args.course_id, bucket=args.bucket or None),\\n                    indent=2,\\n                    default=str,\\n                )\\n            )\\n        elif args.cmd == \\\"brief\\\":\\n            print(\\n                json.dumps(\\n                    api.assignment_brief(args.course_id, args.assignment_id),\\n                    indent=2,\\n                    default=str,\\n                )\\n            )\\n        elif args.cmd == \\\"feedback\\\":\\n            print(\\n                json.dumps(\\n                    api.submission_feedback(args.course_id, args.assignment_id),\\n                    indent=2,\\n                    default=str,\\n                )\\n            )\\n        elif args.cmd == \\\"discussions\\\":\\n            print(json.dumps(api.list_discussion_topics(args.course_id), indent=2, default=str))\\n        elif args.cmd == \\\"files\\\":\\n            print(json.dumps(api.list_files(args.course_id), indent=2, default=str))\\n        elif args.cmd == \\\"export-calendar\\\":\\n            import os\\n\\n            import httpx\\n\\n            from canvaspilot.calendar_export import (\\n                build_assignment_calendar,\\n                write_calendar,\\n            )\\n            from canvaspilot.client import CanvasAuthError, CanvasPaginationError\\n\\n            try:\\n                if os.path.lexists(args.out):\\n                    raise FileExistsError(\\\"Output path already exists; choose a new .ics file\\\")\\n                content, report = build_assignment_calendar(api, args.course_ids, bucket=args.bucket)\\n                write_calendar(args.out, content)\\n            except (CanvasAuthError, CanvasPaginationError, httpx.HTTPError, ValueError, TypeError, OSError) as error:\\n                print(json.dumps({\\n                    \\\"ok\\\": False, \\\"error\\\": type(error).__name__, \\\"message\\\": str(error),\\n                }), file=sys.stderr)\\n                raise SystemExit(1) from None\\n            print(json.dumps({\\\"ok\\\": True, \\\"output\\\": str(args.out), **report}, indent=2))\\n        elif args.cmd == \\\"submission-history\\\":\\n            import httpx\\n\\n            from canvaspilot.client import CanvasAuthError\\n\\n            # MCP initialization can enable HTTPX request logs; keep this CLI\\n            # report machine-readable and restore the caller's logging setting.\\n            http_log = logging.getLogger(\\\"httpx\\\")\\n            previous_level = http_log.level\\n            http_log.setLevel(max(http_log.getEffectiveLevel(), logging.WARNING))\\n            try:\\n                result = api.submission_history(args.course_id, args.assignment_id)\\n            except (CanvasAuthError, httpx.HTTPError, ValueError) as error:\\n                print(json.dumps({\\n                    \\\"ok\\\": False, \\\"error\\\": type(error).__name__, \\\"message\\\": str(error),\\n                }), file=sys.stderr)\\n                raise SystemExit(1) from None\\n            finally:\\n                http_log.setLevel(previous_level)\\n            print(json.dumps(result, indent=2))\\n        elif args.cmd == \\\"module-progress\\\":\\n            import httpx\\n\\n            from canvaspilot.client import CanvasAuthError\\n\\n            try:\\n                result = api.module_progress(args.course_id, module_id=args.module_id)\\n            except (CanvasAuthError, httpx.HTTPError, ValueError) as error:\\n                print(json.dumps({\\n                    \\\"ok\\\": False, \\\"error\\\": type(error).__name__, \\\"message\\\": str(error),\\n                }), file=sys.stderr)\\n                raise SystemExit(1) from None\\n            print(json.dumps(result, indent=2))\\n        elif args.cmd == \\\"browse-files\\\":\\n            import httpx\\n\\n            from canvaspilot.client import CanvasAuthError\\n\\n            try:\\n                result = api.browse_files(\\n                    args.course_id, args.folder_id,\\n                    folders_page=args.folders_page, files_page=args.files_page,\\n                    per_page=args.per_page,\\n                )\\n            except (CanvasAuthError, httpx.HTTPError, ValueError) as error:\\n                print(json.dumps({\\n                    \\\"ok\\\": False, \\\"error\\\": type(error).__name__, \\\"message\\\": str(error),\\n                }), file=sys.stderr)\\n                raise SystemExit(1) from None\\n            print(json.dumps(result, indent=2))\\n    finally:\\n        api.close()\\n\\n\\ndef _session_cmd(args: argparse.Namespace) -> None:\\n    from canvaspilot.client import (\\n        BROKER_PORT,\\n        _broker_request,\\n        broker_base,\\n        broker_health,\\n    )\\n    from canvaspilot.session_broker import main as broker_main\\n\\n    port = getattr(args, \\\"port\\\", None) or BROKER_PORT\\n    if args.scmd == \\\"start\\\":\\n        # foreground — user leaves this running\\n        argv = []\\n        if args.base_url:\\n            argv += [\\\"--base-url\\\", args.base_url]\\n        if args.profile:\\n            argv += [\\\"--profile\\\", args.profile]\\n        argv += [\\\"--port\\\", str(port)]\\n        if getattr(args, \\\"headless\\\", False):\\n            argv.append(\\\"--headless\\\")\\n        if getattr(args, \\\"read_only\\\", False):\\n            argv.append(\\\"--read-only\\\")\\n        broker_main(argv)\\n        return\\n    if args.scmd == \\\"status\\\":\\n        h = broker_health()\\n        if not h:\\n            print(json.dumps({\\\"ok\\\": False, \\\"error\\\": \\\"broker not running\\\", \\\"url\\\": broker_base()}, indent=2))\\n            sys.exit(1)\\n        try:\\n            st = _broker_request(\\\"GET\\\", f\\\"{broker_base()}/status\\\", timeout=30.0).json()\\n        except Exception as exc:  # noqa: BLE001 — report broker comms failures as JSON, never traceback\\n            st = {\\\"error\\\": str(exc)}\\n        print(json.dumps({\\\"health\\\": h, \\\"status\\\": st}, indent=2))\\n        return\\n    if args.scmd == \\\"stop\\\":\\n        try:\\n            r = _broker_request(\\\"POST\\\", f\\\"{broker_base()}/shutdown\\\", json={}, timeout=5.0)\\n            print(r.text)\\n        except Exception as exc:  # noqa: BLE001 — report shutdown failures as JSON, never traceback\\n            print(json.dumps({\\\"ok\\\": False, \\\"error\\\": str(exc)}))\\n            sys.exit(1)\\n\\n\\ndef _login(*, base_url: str | None, profile: str | None) -> None:\\n    from canvaspilot.client import default_base_url, default_profile\\n\\n    try:\\n        from playwright.sync_api import sync_playwright\\n    except ImportError as exc:\\n        raise SystemExit(\\\"pip install canvaspilot[browser]\\\") from exc\\n\\n    base = (base_url or default_base_url()).rstrip(\\\"/\\\")\\n    prof = Path(profile) if profile else default_profile()\\n    prof.mkdir(parents=True, exist_ok=True)\\n    print(json.dumps({\\\"status\\\": \\\"opening\\\", \\\"base_url\\\": base, \\\"profile\\\": str(prof)}, indent=2))\\n    with sync_playwright() as pw:\\n        ctx = pw.chromium.launch_persistent_context(\\n            str(prof),\\n            headless=False,\\n            viewport={\\\"width\\\": 1400, \\\"height\\\": 900},\\n            args=[\\\"--disable-popup-blocking\\\"],\\n        )\\n        page = ctx.pages[0] if ctx.pages else ctx.new_page()\\n        page.goto(base, wait_until=\\\"domcontentloaded\\\")\\n        print(\\n            json.dumps(\\n                {\\n                    \\\"status\\\": \\\"waiting_for_human\\\",\\n                    \\\"message\\\": \\\"Finish SSO/login, then press Enter here.\\\",\\n                },\\n                indent=2,\\n            )\\n        )\\n        try:\\n            input()\\n        except EOFError:\\n            import time\\n\\n            time.sleep(30)\\n        ctx.close()\\n    print(json.dumps({\\\"status\\\": \\\"closed\\\", \\\"profile\\\": str(prof)}, indent=2))\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"encoding\":\"utf-8\",\"sha\":\"5a3ed7be7a24d6461641192a54c77a04b90cc910\",\"display_url\":\"https://github.com/Jacob-Met/canvaspilot/blob/39d835c8becb04d81b65c90d1491d2d3a2727ffe/src/canvaspilot/cli.py\",\"display_title\":\"cli.py\"},\"src/canvaspilot/mcp_server.py\":{\"content\":\"\\\"\\\"\\\"MCP stdio server for Canvas (session/PAT; full REST including quizzes).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import Annotated, Any\\n\\nfrom mcp.server.mcpserver import MCPServer\\nfrom mcp.server.mcpserver.exceptions import ToolError\\nfrom mcp.types import ToolAnnotations\\nfrom pydantic import Field, StrictInt\\n\\nfrom canvaspilot.api import CanvasAPI, _validate_sync_limits\\nfrom canvaspilot.client import CanvasClient\\n\\nmcp = MCPServer(\\n    \\\"canvaspilot\\\",\\n    instructions=(\\n        \\\"Canvas LMS MCP bundle: curated canvas_* tools for common student/ops workflows, \\\"\\n        \\\"plus canvas_api_request / canvas_api_paginated escape hatches for any /api/v1 \\\"\\n        \\\"REST path (session broker or PAT). Prefer curated tools first; use the escape \\\"\\n        \\\"hatch when a named tool is missing. Prefer these over raw browser clicking.\\\"\\n    ),\\n)\\n\\n_api: CanvasAPI | None = None\\n\\n\\ndef _get_api() -> CanvasAPI:\\n    global _api\\n    if _api is None:\\n        _api = CanvasAPI(CanvasClient())\\n    return _api\\n\\n\\ndef _dump(obj: Any) -> str:\\n    return json.dumps(obj, indent=2, default=str)\\n\\n\\n@mcp.tool(description=\\\"Confirm Canvas auth and return self profile.\\\", structured_output=False)\\nasync def canvas_whoami() -> str:\\n    return _dump(_get_api().whoami())\\n\\n\\n@mcp.tool(description=\\\"List active Canvas courses.\\\", structured_output=False)\\nasync def canvas_list_courses() -> str:\\n    return _dump(_get_api().list_courses())\\n\\n\\n@mcp.tool(description=\\\"Get one course including syllabus body when available.\\\", structured_output=False)\\nasync def canvas_get_course(course_id: str) -> str:\\n    return _dump(_get_api().get_course(course_id))\\n\\n\\n@mcp.tool(\\n    description=\\\"List assignments for a course. Default detail=compact (no description bodies). Use detail=full or canvas_assignment_brief for prompts.\\\",\\n    structured_output=False,\\n)\\nasync def canvas_list_assignments(\\n    course_id: str, bucket: str = \\\"upcoming\\\", detail: str = \\\"compact\\\"\\n) -> str:\\n    return _dump(\\n        _get_api().list_assignments(course_id, bucket=bucket or None, detail=detail)\\n    )\\n\\n\\n@mcp.tool(description=\\\"Get one assignment with cleaned prompt text.\\\", structured_output=False)\\nasync def canvas_get_assignment(course_id: str, assignment_id: str) -> str:\\n    return _dump(_get_api().get_assignment(course_id, assignment_id))\\n\\n\\n@mcp.tool(description=\\\"Digested assignment brief: prompt, due date, submission types, and supplied rubric with grading/display settings. Missing rubric data stays unknown; inspect rubric_warnings for omitted malformed data.\\\", structured_output=False)\\nasync def canvas_assignment_brief(course_id: str, assignment_id: str) -> str:\\n    return _dump(_get_api().assignment_brief(course_id, assignment_id))\\n\\n\\n@mcp.tool(\\n    description=\\\"List announcements (compact message_text by default). Pass detail=full for full bodies.\\\",\\n    structured_output=False,\\n)\\nasync def canvas_list_announcements(course_ids: str, detail: str = \\\"compact\\\") -> str:\\n    ids = [c.strip() for c in course_ids.split(\\\",\\\") if c.strip()]\\n    return _dump(_get_api().list_announcements(ids, detail=detail))\\n\\n\\n@mcp.tool(\\n    description=\\\"List modules with items (compact item fields by default). Pass detail=full for raw Canvas payloads.\\\",\\n    structured_output=False,\\n)\\nasync def canvas_list_modules(course_id: str, detail: str = \\\"compact\\\") -> str:\\n    return _dump(_get_api().list_modules(course_id, detail=detail))\\n\\n\\n@mcp.tool(\\n    description=(\\n        \\\"Read Canvas-declared module progress and completed/unfinished/unknown requirements. \\\"\\n        \\\"Optional module_id selects one returned module. Counts cover returned rows only; \\\"\\n        \\\"missing student fields stay unknown. Does not mark items read or complete.\\\"\\n    ),\\n    annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True),\\n    structured_output=False,\\n)\\nasync def canvas_module_progress(course_id: str, module_id: str | None = None) -> str:\\n    return _dump(_get_api().module_progress(course_id, module_id=module_id))\\n\\n\\n@mcp.tool(description=\\\"List wiki pages for a course.\\\", structured_output=False)\\nasync def canvas_list_pages(course_id: str) -> str:\\n    return _dump(_get_api().list_pages(course_id))\\n\\n\\n@mcp.tool(description=\\\"Get a wiki page body by URL slug.\\\", structured_output=False)\\nasync def canvas_get_page(course_id: str, page_url: str) -> str:\\n    return _dump(_get_api().get_page(course_id, page_url))\\n\\n\\n@mcp.tool(description=\\\"List discussion topics for a course.\\\", structured_output=False)\\nasync def canvas_list_discussion_topics(course_id: str) -> str:\\n    return _dump(_get_api().list_discussion_topics(course_id))\\n\\n\\n@mcp.tool(description=\\\"Get a discussion topic + view/entries.\\\", structured_output=False)\\nasync def canvas_get_discussion(course_id: str, topic_id: str) -> str:\\n    return _dump(_get_api().get_discussion(course_id, topic_id))\\n\\n\\n@mcp.tool(description=\\\"Post a reply to a discussion topic.\\\", structured_output=False)\\nasync def canvas_post_discussion_reply(course_id: str, topic_id: str, message: str) -> str:\\n    return _dump(_get_api().post_discussion_reply(course_id, topic_id, message))\\n\\n\\n@mcp.tool(description=\\\"List files in a course.\\\", structured_output=False)\\nasync def canvas_list_files(course_id: str) -> str:\\n    return _dump(_get_api().list_files(course_id))\\n\\n\\n@mcp.tool(\\n    description=(\\n        \\\"Browse metadata in one Canvas course folder. Start with folder_id=root, \\\"\\n        \\\"then choose a returned child folder ID. Requests one bounded folder page \\\"\\n        \\\"and one file page; no downloads or recursive inventory. has_more is unknown; \\\"\\n        \\\"next_page_to_try is an optional probe, not a confirmed next page.\\\"\\n    ),\\n    annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False),\\n    structured_output=False,\\n)\\nasync def canvas_browse_files(\\n    course_id: str,\\n    folder_id: str = \\\"root\\\",\\n    folders_page: StrictInt = 1,\\n    files_page: StrictInt = 1,\\n    per_page: StrictInt = 50,\\n) -> str:\\n    return _dump(_get_api().browse_files(\\n        course_id, folder_id,\\n        folders_page=folders_page, files_page=files_page, per_page=per_page,\\n    ))\\n\\n\\n@mcp.tool(description=\\\"List classic quizzes in a course.\\\", structured_output=False)\\nasync def canvas_list_quizzes(course_id: str) -> str:\\n    return _dump(_get_api().list_quizzes(course_id))\\n\\n\\n@mcp.tool(description=\\\"Get one classic quiz.\\\", structured_output=False)\\nasync def canvas_get_quiz(course_id: str, quiz_id: str) -> str:\\n    return _dump(_get_api().get_quiz(course_id, quiz_id))\\n\\n\\n@mcp.tool(description=\\\"List questions for a classic quiz (when API allows).\\\", structured_output=False)\\nasync def canvas_list_quiz_questions(course_id: str, quiz_id: str) -> str:\\n    return _dump(_get_api().list_quiz_questions(course_id, quiz_id))\\n\\n\\n@mcp.tool(description=\\\"List quiz submissions for a classic quiz.\\\", structured_output=False)\\nasync def canvas_list_quiz_submissions(course_id: str, quiz_id: str) -> str:\\n    return _dump(_get_api().list_quiz_submissions(course_id, quiz_id))\\n\\n\\n@mcp.tool(description=\\\"Start a classic quiz submission (optional access_code).\\\", structured_output=False)\\nasync def canvas_start_quiz_submission(course_id: str, quiz_id: str, access_code: str = \\\"\\\") -> str:\\n    return _dump(\\n        _get_api().start_quiz_submission(\\n            course_id, quiz_id, access_code=access_code or None\\n        )\\n    )\\n\\n\\n@mcp.tool(description=\\\"Complete a classic quiz submission.\\\", structured_output=False)\\nasync def canvas_complete_quiz_submission(\\n    course_id: str,\\n    quiz_id: str,\\n    submission_id: str,\\n    attempt: int = 0,\\n    validation_token: str = \\\"\\\",\\n) -> str:\\n    return _dump(\\n        _get_api().complete_quiz_submission(\\n            course_id,\\n            quiz_id,\\n            submission_id,\\n            attempt=attempt or None,\\n            validation_token=validation_token or None,\\n        )\\n    )\\n\\n\\n@mcp.tool(description=\\\"List Canvas Inbox conversations.\\\", structured_output=False)\\nasync def canvas_list_conversations(scope: str = \\\"inbox\\\") -> str:\\n    return _dump(_get_api().list_conversations(scope=scope))\\n\\n\\n@mcp.tool(description=\\\"Get one Inbox conversation.\\\", structured_output=False)\\nasync def canvas_get_conversation(conversation_id: str) -> str:\\n    return _dump(_get_api().get_conversation(conversation_id))\\n\\n\\n@mcp.tool(description=\\\"List calendar events (optional ISO start/end dates).\\\", structured_output=False)\\nasync def canvas_list_calendar_events(start_date: str = \\\"\\\", end_date: str = \\\"\\\") -> str:\\n    return _dump(\\n        _get_api().list_calendar_events(\\n            start_date=start_date or None,\\n            end_date=end_date or None,\\n        )\\n    )\\n\\n\\n@mcp.tool(description=\\\"Planner items (optional ISO start/end).\\\", structured_output=False)\\nasync def canvas_planner_items(start_date: str = \\\"\\\", end_date: str = \\\"\\\") -> str:\\n    return _dump(\\n        _get_api().planner_items(start_date=start_date or None, end_date=end_date or None)\\n    )\\n\\n\\n@mcp.tool(description=\\\"User activity stream.\\\", structured_output=False)\\nasync def canvas_activity_stream() -> str:\\n    return _dump(_get_api().activity_stream())\\n\\n\\n@mcp.tool(description=\\\"To-do items for the current user.\\\", structured_output=False)\\nasync def canvas_list_todo_items() -> str:\\n    return _dump(_get_api().list_todo_items())\\n\\n\\n@mcp.tool(description=\\\"Self enrollments (default state=active).\\\", structured_output=False)\\nasync def canvas_list_enrollments(state: str = \\\"active\\\") -> str:\\n    return _dump(_get_api().list_enrollments(state=state or \\\"active\\\"))\\n\\n\\n@mcp.tool(\\n    description=\\\"Read upcoming assignments ordered by deadline across courses, with selection counts and per-course read errors.\\\",\\n    structured_output=False,\\n)\\nasync def canvas_sync_summary(\\n    limit_courses: Annotated[int, Field(strict=True, gt=0)] = 10,\\n    limit_assignments_per_course: Annotated[int, Field(strict=True, gt=0)] = 5,\\n) -> str:\\n    _validate_sync_limits(limit_courses, limit_assignments_per_course)\\n    return _dump(_get_api().sync_summary(\\n        limit_courses=limit_courses,\\n        limit_assignments_per_course=limit_assignments_per_course,\\n    ))\\n\\n\\n@mcp.tool(description=\\\"Submission status for an assignment (self).\\\", structured_output=False)\\nasync def canvas_submission_status(course_id: str, assignment_id: str) -> str:\\n    return _dump(_get_api().submission_status(course_id, assignment_id))\\n\\n\\n@mcp.tool(\\n    description=(\\n        \\\"Read self submission comments and rubric feedback with original authors, \\\"\\n        \\\"criteria, and grade/attempt metadata. A false grade_matches_current_submission \\\"\\n        \\\"means grading preceded the latest resubmission. Does not calculate a grade.\\\"\\n    ),\\n    structured_output=False,\\n)\\nasync def canvas_submission_feedback(course_id: str, assignment_id: str) -> str:\\n    return _dump(_get_api().submission_feedback(course_id, assignment_id))\\n\\n\\n@mcp.tool(\\n    description=(\\n        \\\"Read your current assignment submission and returned history, including \\\"\\n        \\\"submitted text, URLs and file/media metadata. Preserves attempt order, \\\"\\n        \\\"unknown history, supplied grades and comment authors without assigning \\\"\\n        \\\"a current grade or comment to another attempt. Does not mark work read.\\\"\\n    ),\\n    annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True),\\n    structured_output=False,\\n)\\nasync def canvas_submission_history(course_id: str, assignment_id: str) -> str:\\n    try:\\n        return _dump(_get_api().submission_history(course_id, assignment_id))\\n    except ValueError as error:\\n        raise ToolError(str(error)) from error\\n\\n\\n@mcp.tool(description=\\\"Submit finished online_text_entry work.\\\", structured_output=False)\\nasync def canvas_submit_assignment_text(course_id: str, assignment_id: str, body: str) -> str:\\n    return _dump(_get_api().submit_assignment_text(course_id, assignment_id, body))\\n\\n\\n@mcp.tool(description=\\\"Reply to an Inbox conversation.\\\", structured_output=False)\\nasync def canvas_reply_conversation(conversation_id: str, body: str) -> str:\\n    return _dump(_get_api().reply_conversation(conversation_id, body))\\n\\n\\n@mcp.tool(\\n    description=(\\n        \\\"Full Canvas REST escape hatch. method=GET|POST|PUT|DELETE|PATCH; \\\"\\n        \\\"path must start with /api/v1 (e.g. /api/v1/users/self). \\\"\\n        \\\"params_json / body_json / form_json are optional JSON objects. \\\"\\n        \\\"Use curated canvas_* tools when they exist; this covers everything else.\\\"\\n    ),\\n    structured_output=False,\\n)\\nasync def canvas_api_request(\\n    method: str,\\n    path: str,\\n    params_json: str = \\\"\\\",\\n    body_json: str = \\\"\\\",\\n    form_json: str = \\\"\\\",\\n) -> str:\\n    params = json.loads(params_json) if params_json.strip() else None\\n    body = json.loads(body_json) if body_json.strip() else None\\n    form = json.loads(form_json) if form_json.strip() else None\\n    return _dump(\\n        _get_api().api_request(\\n            method,\\n            path,\\n            params=params,\\n            json_body=body,\\n            data=form,\\n        )\\n    )\\n\\n\\n@mcp.tool(\\n    description=(\\n        \\\"Paginated GET escape hatch for /api/v1 list endpoints. \\\"\\n        \\\"path must start with /api/v1; params_json optional JSON object.\\\"\\n    ),\\n    structured_output=False,\\n)\\nasync def canvas_api_paginated(path: str, params_json: str = \\\"\\\") -> str:\\n    params = json.loads(params_json) if params_json.strip() else None\\n    return _dump(_get_api().api_paginated(path, params=params))\\n\\n\\ndef main() -> None:\\n    mcp.run()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"encoding\":\"utf-8\",\"sha\":\"f9c470b034a524609f4aedae51479ffd92bfaa8f\",\"display_url\":\"https://github.com/Jacob-Met/canvaspilot/blob/39d835c8becb04d81b65c90d1491d2d3a2727ffe/src/canvaspilot/mcp_server.py\",\"display_title\":\"mcp_server.py\"},\"src/canvaspilot/bundle.py\":{\"content\":\"\\\"\\\"\\\"Canvas MCP + API bundle surface.\\n\\nCurated helpers for common workflows; ``CanvasAPI.api_request`` /\\n``api_paginated`` cover the rest of Canvas REST under ``/api/v1``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom canvaspilot.api import CanvasAPI, assert_canvas_api_path, strip_html\\nfrom canvaspilot.client import CanvasAuthError, CanvasClient, broker_health\\nfrom canvaspilot.mcp_server import mcp\\n\\n# Named MCP tools (plus canvas_api_request / canvas_api_paginated escape hatches).\\nCURATED_MCP_TOOLS: tuple[str, ...] = (\\n    \\\"canvas_whoami\\\",\\n    \\\"canvas_list_courses\\\",\\n    \\\"canvas_get_course\\\",\\n    \\\"canvas_list_assignments\\\",\\n    \\\"canvas_get_assignment\\\",\\n    \\\"canvas_assignment_brief\\\",\\n    \\\"canvas_list_announcements\\\",\\n    \\\"canvas_list_modules\\\",\\n    \\\"canvas_module_progress\\\",\\n    \\\"canvas_list_pages\\\",\\n    \\\"canvas_get_page\\\",\\n    \\\"canvas_list_discussion_topics\\\",\\n    \\\"canvas_get_discussion\\\",\\n    \\\"canvas_post_discussion_reply\\\",\\n    \\\"canvas_list_files\\\",\\n    \\\"canvas_browse_files\\\",\\n    \\\"canvas_list_quizzes\\\",\\n    \\\"canvas_get_quiz\\\",\\n    \\\"canvas_list_quiz_questions\\\",\\n    \\\"canvas_list_quiz_submissions\\\",\\n    \\\"canvas_start_quiz_submission\\\",\\n    \\\"canvas_complete_quiz_submission\\\",\\n    \\\"canvas_list_conversations\\\",\\n    \\\"canvas_get_conversation\\\",\\n    \\\"canvas_reply_conversation\\\",\\n    \\\"canvas_list_calendar_events\\\",\\n    \\\"canvas_planner_items\\\",\\n    \\\"canvas_activity_stream\\\",\\n    \\\"canvas_list_todo_items\\\",\\n    \\\"canvas_list_enrollments\\\",\\n    \\\"canvas_sync_summary\\\",\\n    \\\"canvas_submission_status\\\",\\n    \\\"canvas_submission_feedback\\\",\\n    \\\"canvas_submission_history\\\",\\n    \\\"canvas_submit_assignment_text\\\",\\n    \\\"canvas_api_request\\\",\\n    \\\"canvas_api_paginated\\\",\\n)\\n\\nESCAPE_HATCH_TOOLS: tuple[str, ...] = (\\n    \\\"canvas_api_request\\\",\\n    \\\"canvas_api_paginated\\\",\\n)\\n\\n\\ndef make_api(*, token: str | None = None, fixture: dict | None = None) -> CanvasAPI:\\n    \\\"\\\"\\\"Programmatic API bundle (same auth modes as MCP).\\\"\\\"\\\"\\n    return CanvasAPI(CanvasClient(token=token, fixture=fixture))\\n\\n\\ndef tool_inventory() -> dict[str, object]:\\n    return {\\n        \\\"server\\\": \\\"canvaspilot\\\",\\n        \\\"curated\\\": list(CURATED_MCP_TOOLS),\\n        \\\"escape_hatches\\\": list(ESCAPE_HATCH_TOOLS),\\n        \\\"coverage\\\": \\\"curated student/ops workflows + full /api/v1 via escape hatch\\\",\\n        \\\"limits\\\": [\\n            \\\"New Quizzes / LTI tools are not first-class; classic quizzes are\\\",\\n            \\\"writes (submit, reply, quiz start) require live auth and human judgment\\\",\\n        ],\\n    }\\n\\n\\n__all__ = [\\n    \\\"CURATED_MCP_TOOLS\\\",\\n    \\\"ESCAPE_HATCH_TOOLS\\\",\\n    \\\"CanvasAPI\\\",\\n    \\\"CanvasAuthError\\\",\\n    \\\"CanvasClient\\\",\\n    \\\"assert_canvas_api_path\\\",\\n    \\\"broker_health\\\",\\n    \\\"make_api\\\",\\n    \\\"mcp\\\",\\n    \\\"strip_html\\\",\\n    \\\"tool_inventory\\\",\\n]\\n\",\"encoding\":\"utf-8\",\"sha\":\"23badab9d8ea96b4ed30fb2b5f32f773c910c7f9\",\"display_url\":\"https://github.com/Jacob-Met/canvaspilot/blob/39d835c8becb04d81b65c90d1491d2d3a2727ffe/src/canvaspilot/bundle.py\",\"display_title\":\"bundle.py\"},\"README.md\":{\"content\":\"# CanvasPilot\\n\\nAgentic Canvas LMS tools for LLMs — an **MCP server + CLI** that talks to Canvas's real REST API using the session your browser already has.\\n\\nMost Canvas MCPs need a Personal Access Token. Many schools disable student PATs and hide Canvas behind SSO/MFA. CanvasPilot solves that with a **stay-open session broker**: you log in once in a real browser (Playwright, persistent profile), then every tool call rides that authenticated session — headless, for as long as the cookies live.\\n\\nSame architecture as OpenCLI-style web agents (persistent browser session → site's real HTTP/JSON API), purpose-built for Canvas.\\n\\n## Features\\n\\n- **Auth designed for real schools** — session broker (SSO/MFA, no PAT needed) *or* classic `CANVAS_API_TOKEN`\\n- **Headless after one headed login** — `session start --headless` reuses the saved profile\\n- **Full REST surface** — courses, assignments, modules, pages, files, discussions, announcements, planner, inbox, calendar, activity stream, submissions, and **quizzes** (list/questions/submissions/start/complete)\\n- **Agent-shaped digests** — `assignment_brief` (cleaned prompt + rubric), `sync_summary` (courses + upcoming), `submission_status`\\n- **Submission feedback** — self submission comments and rubric assessments alongside current-attempt and grading metadata\\n- **Submission history** — inspect returned attempts and submitted text/file metadata without assigning current grades or comments to earlier versions ([guide](docs/submission-history.md))\\n- **Fixture mode** — offline dict backend for tests and CI; no Canvas required\\n- **37 MCP tools**, one stdio server, one env var for the host (`CANVAS_BASE_URL`) plus either a PAT or a running session broker\\n- **Course folder browsing** — select nested folders and inspect bounded file-metadata pages through CLI, MCP or Python\\n- **Module progress checklist** — review reported completion, remaining requirements and module locks through CLI, MCP or Python\\n\\n## Install\\n\\nNot published to PyPI yet — install from a checkout:\\n\\n```bash\\ngit clone https://github.com/Jacob-Met/canvaspilot.git\\ncd canvaspilot\\npip install -e \\\".[browser]\\\"\\nplaywright install chromium\\n```\\n\\nRequires Python 3.11+.\\n\\n## Try it offline first\\n\\nFrom an installed package or an editable source checkout:\\n\\n```bash\\npython -m canvaspilot.offline_demo\\n# Optional: save to a NEW path (existing files are protected)\\npython -m canvaspilot.offline_demo --out synthetic-review.json\\n```\\n\\nThis exercises the high-level course and assignment-brief API on two explicitly\\nsynthetic courses. It strips prompt markup, preserves a missing due date as\\nunknown, and returns readable JSON. No Canvas account, browser, token, session\\nbroker, model call, submission, or runtime network connection is needed. The\\nexample rejects writes and missing fixture routes instead of falling back to\\nlive access. Installing package dependencies requires network access separately.\\n\\nThis is a small, inspectable behavior demonstration, not evidence of live\\npagination, working school authentication, or student outcomes. The tests in\\n`tests/test_offline_demo.py` protect these boundaries.\\n\\n## Quick start\\n\\n```bash\\nexport CANVAS_BASE_URL=https://<school>.instructure.com\\n\\n# 1) Log in once (headed — finish SSO/MFA in the window), leave the broker running\\ncanvaspilot session start\\n\\n# 2) Later: restart headless on the same saved profile\\ncanvaspilot session start --headless\\n\\n# 3) Use it\\ncanvaspilot whoami\\ncanvaspilot courses\\ncanvaspilot sync\\ncanvaspilot brief <course_id> <assignment_id>\\ncanvaspilot feedback <course_id> <assignment_id>\\ncanvaspilot submission-history <course_id> <assignment_id>\\n```\\n\\n`canvaspilot sync` orders upcoming assignments by deadline across the selected\\ncourses. It includes up to 10 courses and 5 assignments per course by default,\\nand reports omitted rows, unknown dates, and per-course read failures. Adjust\\nthe overview with `--limit-courses` and `--limit-assignments-per-course`; see\\n[the sync guide](docs/SYNC.md) for CLI, Python, and MCP examples and count meanings.\\n\\nAssignment lists and sync rows also include the current user's reported\\nsubmission state, attempt, and late/missing/excused flags when Canvas supplies\\nthem. Missing data remains unknown; the existing `has_submitted_submissions`\\nflag describes submissions by any student. See the\\n[assignment submission guide](docs/assignment-submission.md) for field meanings,\\nselection examples and malformed-data warnings.\\n\\nTo take selected course deadlines into a calendar application, save an explicit\\nlocal snapshot with `canvaspilot export-calendar 42 77 --out deadlines.ics`.\\nThe [calendar export guide](docs/calendar-export.md) explains selection,\\nundated omissions, snapshot limits and safe re-import expectations.\\n\\nWith a PAT instead:\\n\\n```bash\\nexport CANVAS_API_TOKEN=...   # broker not needed\\ncanvaspilot courses\\n```\\n\\n## Assignment briefs\\n\\n`canvaspilot brief <course_id> <assignment_id>`, the Python\\n`CanvasAPI.assignment_brief()` method, and the MCP `canvas_assignment_brief` tool\\nreturn the same JSON brief: the cleaned prompt, due date, assignment points,\\nsubmission types, Canvas link, and the rubric supplied with the assignment.\\n\\n- `rubric` preserves the supplied criterion and rating order, IDs, descriptions,\\n  long descriptions, points (including zero), range/scoring flags, and outcome\\n  identifiers. Rubric text is not rewritten. Only these canonical rubric fields\\n  are projected; `get_assignment()` retains the complete original rubric payload.\\n- `rubric_settings` preserves the supplied settings object, including any display\\n  flags such as `hide_points`, `hide_score_total`, and free-form criterion comments.\\n  The CLI and MCP return data, without rendering a Canvas rubric UI. Consumers\\n  should honor the distinct display flags when rendering it.\\n- `use_rubric_for_grading` preserves Canvas's boolean: `false` means the rubric is\\n  advisory; `null` means the assignment response did not supply a usable value.\\n- `rubric_warnings` is normally empty. Malformed optional containers, entries, or\\n  canonical field values are omitted locally with a warning that names their\\n  location, while the ordinary brief and usable neighboring entries remain.\\n\\nA missing or `null` rubric remains `null`; a supplied empty list remains `[]`.\\nMissing criterion fields are not filled in, and missing ratings remain unknown.\\nNo criteria, score totals, or grading requirements are inferred. Assignment\\n`points_possible` and rubric settings' `points_possible` remain separate supplied\\nvalues. This uses the existing assignment GET request, without another rubric\\nrequest or a change to authentication.\\n\\nThe field meanings follow Canvas's [Assignments API](https://developerdocs.instructure.com/services/canvas/resources/assignments)\\nand [Rubrics API](https://developerdocs.instructure.com/services/canvas/resources/rubrics).\\nThe public-path tests in `tests/test_assignment_brief_rubric.py` use a clearly\\nsynthetic assignment and forbid HTTP and broker access.\\n\\n## MCP server\\n\\n```bash\\ncanvaspilot mcp          # stdio\\n```\\n\\nCursor / Claude Desktop / any MCP client:\\n\\n```json\\n{\\n  \\\"mcpServers\\\": {\\n    \\\"canvas\\\": {\\n      \\\"command\\\": \\\"canvaspilot\\\",\\n      \\\"args\\\": [\\\"mcp\\\"],\\n      \\\"env\\\": { \\\"CANVAS_BASE_URL\\\": \\\"https://<school>.instructure.com\\\" }\\n    }\\n  }\\n}\\n```\\n\\nTools exposed (all prefixed `canvas_`):\\n\\n| Area | Tools |\\n|------|-------|\\n| Identity | `whoami`, `sync_summary`, `planner_items`, `activity_stream`, `list_todo_items`, `list_enrollments` |\\n| Courses | `list_courses`, `get_course`, `list_modules`, `module_progress`, `list_pages`, `get_page`, `list_files`, `browse_files`, `list_announcements` |\\n| Assignments | `list_assignments`, `get_assignment`, `assignment_brief`, `submission_status`, `submission_feedback`, `submission_history`, `submit_assignment_text` |\\n| Discussions | `list_discussion_topics`, `get_discussion`, `post_discussion_reply` |\\n| Quizzes | `list_quizzes`, `get_quiz`, `list_quiz_questions`, `list_quiz_submissions`, `start_quiz_submission`, `complete_quiz_submission` |\\n| Inbox / Calendar | `list_conversations`, `get_conversation`, `reply_conversation`, `list_calendar_events` |\\n| **Full REST** | `canvas_api_request`, `canvas_api_paginated` — any `/api/v1/...` path, including paginated reads through a current session broker (see Auth modes for collection requirements) |\\n\\nProgrammatic API bundle: `from canvaspilot.bundle import make_api, tool_inventory`.\\n\\n### Submission feedback\\n\\nUse `canvaspilot feedback <course_id> <assignment_id>`, the MCP tool\\n`canvas_submission_feedback`, or `CanvasAPI.submission_feedback(course_id, assignment_id)`\\nto review your submission comments and rubric evidence together. The report uses\\nthe [assignment](https://developerdocs.instructure.com/services/canvas/resources/assignments)\\nand [self submission](https://developerdocs.instructure.com/services/canvas/resources/submissions)\\nGET endpoints, requesting `submission_comments` and `rubric_assessment`. It uses\\nthe selected client's existing authentication and returns only what Canvas exposes\\nto that user.\\n\\nThe JSON report contains:\\n\\n- `assignment`: the assignment's identity, title, URL, due date, and possible points.\\n- `submission`: Canvas's score, grade, attempt, workflow state, grader ID, and\\n  submission/grading timestamps. A false `grade_matches_current_submission` means\\n  the student resubmitted since grading; the displayed grade may describe an\\n  earlier attempt. A missing flag remains `null`. Negative grader IDs are retained\\n  because Canvas can identify an autograder that way.\\n- `rubric.criteria`: each original `criterion` beside its `assessment`, joined\\n  only by a unique exact string criterion ID. Criterion descriptions, ratings,\\n  `ignore_for_scoring`, and `criterion_use_range` remain available. Missing or\\n  ambiguous IDs leave the assessment in `rubric.unmatched_assessments`, keyed by\\n  its original ID. Assessment points and comments are preserved as returned.\\n- `rubric.use_rubric_for_grading` and `rubric.settings`: Canvas's grading/advisory\\n  distinction and rubric settings. The report does not sum rubric points or infer\\n  a grade. `assessment_returned` says whether Canvas returned an assessment object,\\n  including an empty object; it does not mean the submission has been graded.\\n- `submission_comments`: original comment objects, including authors, timestamps,\\n  media comments, and attachments when supplied. Students and peers can also\\n  author these comments. Media-only comments remain present.\\n\\nZero marks remain zero. Missing/null comments or rubric data remain `null`, while\\nexplicitly returned empty arrays/maps remain empty. A criterion with no matching\\nassessment has `assessment: null`; omitted assessment points or comments remain\\nomitted. An inaccessible submission or malformed response is reported as an error,\\nso it cannot be mistaken for a submission with no feedback. This operation performs\\ntwo GETs and does not mark comments read, submit work, or change a grade.\\n\\n### Announcements\\n\\n`canvas_list_announcements` and `CanvasAPI.list_announcements()` use the existing\\nclient paginator in both compact and full detail modes. Course and optional start-date\\nfilters are retained, and results keep Canvas's page order and announcement metadata.\\nCompact message text remains limited to 400 characters plus an ellipsis; full detail\\nretains the complete stripped text. A failed page request raises an error instead of\\nreturning the announcements collected before the failure. The selected client's\\nexisting transport and pagination limits still apply.\\n\\n### Module contents\\n\\n`canvas_list_modules` and `CanvasAPI.list_modules()` retrieve module items even\\nwhen Canvas omits the optional inline `items` array. Missing, null, malformed, or\\nshorter inline contents are fetched through the existing paginated module-items\\nroute; valid complete inline arrays and modules reporting an integer zero need no extra\\nrequest. Compact output retains its existing item fields; `detail=full` preserves\\nCanvas's module metadata and the retrieved item payloads. A failed secondary\\nrequest or malformed item response is reported to the caller instead of being\\npresented as an empty module.\\n\\nThis follows the [Canvas Modules API](https://developerdocs.instructure.com/services/canvas/resources/modules)\\ncontract. Requests use the selected client's existing fixture, token, or session\\nbroker transport and pagination limits. Listing does not mark module items read\\nor complete.\\n\\n## Review module progress\\n\\n```bash\\ncanvaspilot module-progress 42\\ncanvaspilot module-progress 42 --module-id 7\\n```\\n\\nReview Canvas-declared module states and completed, unfinished or unknown item\\nrequirements. The checklist keeps all-versus-one requirements, prerequisites and\\nsequential-progress context. Missing student fields stay unknown; counts cover\\nreturned rows. This read-only workflow never marks items read or complete. See\\n[the module-progress guide](docs/module-progress.md) for Python/MCP examples and\\ncoverage meanings.\\n\\n## Browse course folders\\n\\n```bash\\ncanvaspilot browse-files 42\\ncanvaspilot browse-files 42 --folder-id 110 --files-page 2 --per-page 20\\n```\\n\\nStart at the course root, then choose a returned child folder ID. Each result\\ncontains the selected folder and one requested page each of direct child folders\\nand files. Only metadata is returned; file bodies and download/preview URLs are\\nexcluded. A foreign folder or permission failure returns an error, not an empty\\nlisting. `has_more` is unknown because the existing request interface omits\\npagination headers; `next_page_to_try` is an optional probe, not a completeness\\nclaim. See [folder-browser usage and contract](docs/folder-browser.md) for the\\nMCP/Python interfaces, page limits and examples.\\n\\n## Auth modes\\n\\n| Mode | How | When |\\n|------|-----|------|\\n| **session** (default) | Playwright persistent profile + local broker on `127.0.0.1:18765` | School disables student PATs / SSO+MFA |\\n| **token** | `CANVAS_API_TOKEN` → `Authorization: Bearer` | School allows PATs |\\n| **fixture** | `CanvasClient(fixture={...})` | Tests, offline demos |\\n\\nMode resolution is fixture > token > live broker > session, decided at runtime: `CANVAS_API_TOKEN` always wins and skips the broker; otherwise a live `GET 127.0.0.1:18765/health` probe decides whether the session broker is used. Bare \\\"session\\\" mode with no running broker raises on every request — \\\"session (default)\\\" means \\\"broker if it's up\\\", not \\\"works with no setup\\\".\\n\\nPagination follows Canvas's response `Link` headers in token mode and in current\\nsession brokers. A session broker advertises `\\\"link_pagination\\\": true` in\\n`GET /health` and forwards only the `Link` response header alongside each fetch\\nresult. The client follows an opaque `rel=next` URL even when a page is shorter\\nthan the requested `per_page`; it stops when no next link remains, without\\ninventing a numeric page or requesting an extra empty page. Initial filters and\\nrepeated `include[]` values apply only to the first request; subsequent URLs\\nretain the server's exact parameters. Ordinary single-request results keep their\\nexisting decoded JSON/text shape.\\n\\nToken collection reads validate both the initial URL and each next URL against\\nthe client's configured Canvas scheme, host and effective port before dispatch.\\nInitial absolute URLs retain their authored query and receive the initial\\nfilters once. Session continuation stays on the broker's configured Canvas\\norigin and retains the exact absolute continuation URL.\\n\\nEach applicable Link entry must carry a valid relation. Anchored links are\\nignored as whole entries because they change the context; registered relation\\nnames such as `next` are matched without regard to case. Quoted parameter values\\nand absolute URI extension relations remain supported. Invalid or ambiguous\\nmetadata, repeated continuation URLs, a later-page error or non-list body, and\\na known continuation beyond the 40-page limit raise an error. A terminal first\\nsingle-object response keeps its existing convention. `CanvasPaginationError`\\nis available from `canvaspilot.client`.\\n\\nAn older running broker without the capability flag produces an actionable\\nincomplete-collection error. Restart it with the current CanvasPilot version and\\nretry the read. Ordinary single requests remain compatible with older brokers.\\nThe [Canvas pagination contract](https://developerdocs.instructure.com/services/canvas/basics/file.pagination)\\nexplains why clients must check Link even when they request a page size.\\n\\nThe broker only listens on loopback — and `session_broker.main()` now refuses to start on any non-loopback bind address (fail-closed: a future host change cannot silently expose the unauthenticated `/fetch`/`/shutdown` endpoints to the network). Cookies never leave the Playwright profile directory; the MCP/CLI process never sees them — it asks the broker to make the request.\\n\\n## Configuration\\n\\n| Env | Default | Purpose |\\n|-----|---------|---------|\\n| `CANVAS_BASE_URL` | `https://canvas.instructure.com` | Your school's Canvas host |\\n| `CANVAS_API_TOKEN` | — | PAT (skips the broker) |\\n| `CANVAS_PROFILE` | `~/.canvaspilot/profile` | Playwright persistent profile dir |\\n| `CANVAS_SESSION_PORT` | `18765` | Broker port |\\n| `CANVASPILOT_REPORTS` | `~/.canvaspilot/reports` | Output dir for `scripts/` sweeps |\\n\\n## Session broker commands\\n\\n```bash\\ncanvaspilot session start [--headless] [--base-url URL] [--profile DIR] [--port N] [--read-only]\\ncanvaspilot session status\\ncanvaspilot session stop\\n```\\n\\n`--read-only` is for unattended agent use: the broker rejects non-GET/HEAD\\n`/fetch` ops with 403, so a runaway agent cannot mutate Canvas through the\\nsession. `GET /health` advertises the mode (`\\\"read_only\\\": true|false`), so\\nclients can discover it. It is orthogonal to broker authentication (see issue\\n#5) — it limits *what* the broker can do, not *who* can call it.\\n\\n## Scripts\\n\\n- `scripts/readonly_sweep.py` — live read-only smoke across the whole tool surface (needs a running broker)\\n- `scripts/inventory_pass.py` — per-course inventory: tabs, LTI/external tools, modules, third-party mentions\\n\\n## Development\\n\\n```bash\\npip install -e \\\".[dev]\\\"\\npytest\\n```\\n\\nTests use offline fixtures and disposable loopback HTTP servers. Feedback tests\\nalso exercise CLI subprocesses and the real MCP stdio interface; no Canvas account\\nor running browser is needed.\\n\\nThe optional native-browser check executes the production in-page fetch against\\nan authored loopback response in a fresh Chromium profile. It uses no school\\nsession and verifies that the fixture cookie remains in the browser while only\\nLink metadata reaches the caller:\\n\\n```bash\\nCANVASPILOT_CHROMIUM_BIN=/path/to/chromium python -m pytest -q tests/test_browser_link_metadata.py\\n```\\n\\n`CANVASPILOT_CHROMIUM_PROFILE_ROOT` can select a writable parent for temporary\\nprofiles (useful for a confined browser package). The browser test skips only\\nwhen `CANVASPILOT_CHROMIUM_BIN` is unset; an invalid configured executable fails.\\nAll regular HTTP/client tests run offline without a browser binary.\\n\\n## Responsible use\\n\\nCanvasPilot gives an agent the same access you have — including submitting assignments and starting quiz attempts. Write tools are clearly named; wire approval gates in your agent if you don't want autonomous submits. Follow your institution's academic integrity policy.\\n\\nWrite caveats: the write path has no CSRF handling and has not been validated against live Canvas session authentication — submitting from session-broker mode may fail or behave unexpectedly. The author has not used the write tools against a live school; they exist as capability, not as a tested workflow.\\n\\n## Origin\\n\\nExtracted from the Suite monorepo (`packages/canvaspilot`), where it's synced via `git subtree`. (The monorepo is not publicly accessible; the link resolves for authorized collaborators.)\\n\\n## License\\n\\nMIT\\n\\n## Maintainer\\n\\n[Jacob Metoyer](https://jacobmetoyer.com/) — software and research tooling.\\nUpstream and collaborator credit are retained.\\n\\n\",\"encoding\":\"utf-8\",\"sha\":\"083dc576676240d388921d292fedef7d7c8ccce3\",\"display_url\":\"https://github.com/Jacob-Met/canvaspilot/blob/39d835c8becb04d81b65c90d1491d2d3a2727ffe/README.md\",\"display_title\":\"README.md\"}}")
seams=json.loads("[{\"path\":\"src/canvaspilot/api.py\",\"kind\":\"insert\",\"next_context\":\"    def post_discussion_reply(\\n\",\"inserted\":\"    def discussion_thread(\\n        self, course_id: int | str, topic_id: int | str, *, unread_only: bool = False\\n    ) -> dict[str, Any]:\\n        \\\"\\\"\\\"Read the cached discussion tree with explicit read state and reply context.\\\"\\\"\\\"\\n        from canvaspilot.discussion_thread import (\\n            build_discussion_thread,\\n            validate_discussion_selection,\\n        )\\n\\n        course, topic = validate_discussion_selection(course_id, topic_id, unread_only)\\n        result = self.get_discussion(course, topic)\\n        return build_discussion_thread(result[\\\"topic\\\"], result[\\\"view\\\"], unread_only=unread_only)\\n\\n\"},{\"path\":\"src/canvaspilot/cli.py\",\"kind\":\"insert\",\"next_context\":\"        elif args.cmd == \\\"files\\\":\\n\",\"inserted\":\"        elif args.cmd == \\\"discussion\\\":\\n            import httpx\\n\\n            from canvaspilot.client import CanvasAuthError\\n\\n            try:\\n                result = api.discussion_thread(\\n                    args.course_id, args.topic_id, unread_only=args.unread_only\\n                )\\n            except (CanvasAuthError, httpx.HTTPError, ValueError) as error:\\n                print(json.dumps({\\n                    \\\"ok\\\": False, \\\"error\\\": type(error).__name__, \\\"message\\\": str(error),\\n                }), file=sys.stderr)\\n                raise SystemExit(1) from None\\n            print(json.dumps(result, indent=2))\\n\"},{\"path\":\"src/canvaspilot/cli.py\",\"kind\":\"insert\",\"next_context\":\"    files = sub.add_parser(\\\"files\\\", help=\\\"List course files\\\")\\n\",\"inserted\":\"    discussion = sub.add_parser(\\n        \\\"discussion\\\", help=\\\"Read one cached discussion; unread focus retains reply context\\\"\\n    )\\n    add_common(discussion)\\n    discussion.add_argument(\\\"course_id\\\", help=\\\"Positive numeric Canvas course ID\\\")\\n    discussion.add_argument(\\\"topic_id\\\", help=\\\"Positive numeric Canvas discussion topic ID\\\")\\n    discussion.add_argument(\\n        \\\"--unread-only\\\", action=\\\"store_true\\\", help=\\\"Keep known unread entries and their ancestors\\\"\\n    )\\n\\n\"},{\"path\":\"src/canvaspilot/mcp_server.py\",\"kind\":\"insert\",\"next_context\":\"\\n\\n@mcp.tool(description=\\\"Post a reply to a discussion topic.\\\", structured_output=False)\\n\",\"inserted\":\"\\n\\n@mcp.tool(\\n    description=(\\n        \\\"Read a Canvas cached discussion tree with source entry fields, author attribution \\\"\\n        \\\"and reported read markers. unread_only retains known unread entries and their \\\"\\n        \\\"ancestors as context. The cached view is eventually consistent; unknown or \\\"\\n        \\\"unlocated read markers remain explicit. Does not post or mark entries read.\\\"\\n    ),\\n    annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False),\\n    structured_output=False,\\n)\\nasync def canvas_discussion_thread(\\n    course_id: str, topic_id: str, unread_only: StrictBool = False\\n) -> str:\\n    return _dump(_get_api().discussion_thread(course_id, topic_id, unread_only=unread_only))\\n\"},{\"path\":\"src/canvaspilot/mcp_server.py\",\"kind\":\"replace\",\"before\":\"from pydantic import Field, StrictInt\\n\",\"after\":\"from pydantic import Field, StrictBool, StrictInt\\n\"},{\"path\":\"src/canvaspilot/bundle.py\",\"kind\":\"insert\",\"next_context\":\"    \\\"canvas_post_discussion_reply\\\",\\n\",\"inserted\":\"    \\\"canvas_discussion_thread\\\",\\n\"},{\"path\":\"README.md\",\"kind\":\"insert\",\"next_context\":\"\\n### Announcements\\n\",\"inserted\":\"\\n### Read a discussion\\n\\nAfter choosing a topic with `canvaspilot discussions <course_id>`, open it with\\n`canvaspilot discussion <course_id> <topic_id>`. Add `--unread-only` to keep known\\nunread replies together with their parent context. The same report is available\\nthrough `CanvasAPI.discussion_thread()` and `canvas_discussion_thread` in MCP.\\n\\nThe report keeps original entry fields and the returned reply structure, alongside\\ncleaned text, unambiguous author attribution and reported read markers. Missing\\nfacts remain unknown; absent or ambiguous unread metadata does not become a\\nfalse empty result. Canvas's cached-view boundary and unmatched unread identifiers\\nremain visible. See [the discussion reader guide](docs/DISCUSSIONS.md) for fields,\\nselection rules and error behavior.\\n\"},{\"path\":\"README.md\",\"kind\":\"replace\",\"before\":\"| Discussions | `list_discussion_topics`, `get_discussion`, `post_discussion_reply` |\\n\",\"after\":\"| Discussions | `list_discussion_topics`, `get_discussion`, `discussion_thread`, `post_discussion_reply` |\\n\"},{\"path\":\"README.md\",\"kind\":\"current owner count plus one\",\"before\":\"37 MCP tools\",\"after\":\"38 MCP tools\"}]")
out={}
for p,b in bases.items():
 before=b['content'];after=(root/p).read_text()
 raw=before.encode();assert hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()==b['sha'],p
 recovered=after
 changes=[]
 for s in reversed([s for s in seams if s['path']==p]):
  if s['kind']=='insert':
   assert recovered.count(s['inserted'])==1,p
   recovered=recovered.replace(s['inserted'],'',1);changes.append({'kind':'remove_exact_insertion','bytes':len(s['inserted'].encode())})
  elif s['kind']=='replace':
   assert recovered.count(s['after'])==1,p
   recovered=recovered.replace(s['after'],s['before'],1);changes.append({'kind':'reverse_exact_replace','bytes':len(s['after'].encode())})
  elif s['kind']=='current owner count plus one':
   assert recovered.count(s['after'])==1,p
   recovered=recovered.replace(s['after'],s['before'],1);changes.append({'kind':'reverse_catalog_count'})
  else: raise AssertionError(s)
 assert recovered==before,p
 owner_functions=None
 if p.endswith(('api.py','mcp_server.py')):
  def funcs(t):return {n.name:ast.dump(n,include_attributes=False) for n in ast.walk(ast.parse(t)) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
  old,new=funcs(before),funcs(after)
  assert all(new.get(k)==v for k,v in old.items()),p
  owner_functions=len(old)
 out[p]={'primary_blob':b['sha'],'candidate_sha256':hashlib.sha256(after.encode()).hexdigest(),'all_current_base_bytes_recovered_exactly':True,'owner_functions_ast_exact':owner_functions,'reverse_changes':changes}
